# There are two markers: one '2' at (4,14)? input has single 2 at row4 col14? check
for r,row in enumerate(I):
    if 2 in row: print('2 at',r,row.index(2))
    if 3 in row: print('3 at',r,row.index(3))
# changed cells positions: out!=in
ch=[(r,c,I[r][c],O[r][c]) for r in range(30) for c in range(30) if I[r][c]!=O[r][c]]
import collections
print(len(ch), collections.Counter((a,b) for _,_,a,b in ch))

def comps(g,val=1):
    seen=set(); out=[]
    H,W=len(g),len(g[0])
    for r in range(H):
        for c in range(W):
            if g[r][c]==val and (r,c) not in seen:
                st=[(r,c)]; comp=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen or not(0<=a<H and 0<=b<W) or g[a][b]!=val: continue
                    seen.add((a,b)); comp.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        st.append((a+da,b+db))
                out.append(comp)
    return out
cs=comps(I)
for i,c in enumerate(cs):
    rs=[a for a,b in c]; cc=[b for a,b in c]
    h=max(rs)-min(rs)+1; w=max(cc)-min(cc)+1
    area=h*w
    cols=collections.Counter(O[a][b] for a,b in c)
    print(i,'size',len(c),'bbox h,w',h,w,'fill',cols, 'rect' if len(c)==area else '')

hcells=[(a,b) for a in range(H) for b in range(W) if not vis[a][b]]
def gcomp(pts):
    seen=set(); res=[]
    for p in pts:
        if p in seen: continue
        st=[p]; seen.add(p); cur=[]
        while st:
            a,b=st.pop(); cur.append((a,b))
            for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                q=(a+da,b+db)
                if q in set(pts) and q not in seen:
                    seen.add(q); st.append(q)
        res.append(cur)
    return res
hg=gcomp(hcells)
print(len(hg))
