def rects(I):
    res=[]
    H,W=len(I),len(I[0])
    for r0 in range(H):
        for c0 in range(W):
            for h in range(2,H-r0+1):
                if not any((r0,c) != (r,c) or True for _ in [0]): pass
                for w in range(2,W-c0+1):
                    r1=c0+w-1
                    ok=all(I[r][c]==1 for r in range(r0,r0+h) for c in range(c0,c0+w))
                    if ok: continue
                    # try: rect of exactly 1s including border? require border 1s
                    border=[I[r][c] for r in range(r0,r0+h) for c in ((c0,),(r0+c0,h-1)))
                    inner=[(r,c) for r in range(r0+1,r0+h-1) for c in range(c0+1,c0+w-1)]
                    res.append((r0,c0,h,w,border==[1]*2*h+2*(w-2),inner))
    return res
# too broad; restrict: border all 1, and interior empty of 1s, but interior may contain marker or 0
def candidate_rects(I):
