import os,glob,re,collections
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
I=G['Demo pair 1 input']; O=G['Demo pair 1 output']
def candidate_rects(I):
    res=[]; H,W=len(I),len(I[0])
    for r0 in range(H):
        for c0 in range(W):
            if I[r0][c0]!=1: continue
            for h in range(2,H-r0+1):
                if not all(I[r0+i][c0]==1 for i in range(h)): continue
                for w in range(2,W-c0+1):
                    if not all(I[r0+i][c0+w-1]==1 for i in range(h)): continue
                    if not all(I[r0+h-1][c0+c]==1 for c in range(w)): continue
                    if not all(I[r0][c0+c]==1 for c in range(w)): continue
                    inner={(r0+i,c0+c) for i in range(1,h-1) for c in range(1,w-1)}
                    if any(I[a][b]==1 for a,b in inner): continue
                    res.append((r0,c0,h,w,inner))
    return res
for (r0,c0,h,w,inn) in candidate_rects(I):
    colset=collections.Counter(O[a][b] for a in range(r0,r0+h) for b in range(c0,c0+w) if I[a][b]==1)
    marks=collections.Counter(I[a][b] for a,b in inn if I[a][b]!=0)
    print((r0,c0,h,w),'innermarks',dict(marks),'rectout',dict(colset))

