def comps_of(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==1 and not seen[r][c]:
                st=[(r,c)]; comp=[]; seen[r][c]=True
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        ra,ca=a+da,b+db
                        if 0<=ra<H and 0<=ca<W and g[ra][ca]==1 and not seen[ra][ca]:
                            seen[ra][ca]=True; st.append((ra,ca))
                out.append(comp)
    return out
